     1→/**
     2→ * FreeLang Nexus Phase 9 - 배열 지원 테스트
     3→ */
     4→
     5→import NexusLexer from '../src/nexus/lexer/nexus-lexer';
     6→import { NexusParser } from '../src/nexus/parser/nexus-parser';
     7→import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
     8→
     9→describe('FreeLang Nexus Phase 9 - 배열 지원', () => {
    10→  /**
    11→   * Test 1: 배열 리터럴 파싱 [1, 2, 3]
    12→   */
    13→  test('Test 1: 배열 리터럴 파싱 [1, 2, 3]', () => {
    14→    const code = `@mode(v)
    15→fn test() -> i64 {
    16→  let arr = [1, 2, 3]
    17→  return 0
    18→}`;
    19→    const lexer = new NexusLexer(code);
    20→    const tokens = lexer.tokenize();
    21→    const parser = new NexusParser(tokens);
    22→    const ast = parser.parse();
    23→
    24→    // AST 검증: 배열 리터럴이 파싱되어야 함
    25→    expect(ast.body.length).toBe(1);
    26→    const fn = ast.body[0] as any;
    27→    expect(fn.type).toBe('VFunction');
    28→    // let arr = [...], return 0 → 2개 문장
    29→    expect(fn.body.length).toBe(2);
    30→    const stmt = fn.body[0] as any;
    31→    expect(stmt.type).toBe('Assign');
    32→    expect(stmt.value.type).toBe('Array');
    33→    expect(stmt.value.elements.length).toBe(3);
    34→  });
    35→
    36→  /**
    37→   * Test 2: 빈 배열 파싱 []
    38→   */
    39→  test('Test 2: 빈 배열 파싱 []', () => {
    40→    const code = `@mode(v)
    41→fn test() -> i64 {
    42→  let empty = []
    43→  return 0
    44→}`;
    45→    const lexer = new NexusLexer(code);
    46→    const tokens = lexer.tokenize();
    47→    const parser = new NexusParser(tokens);
    48→    const ast = parser.parse();
    49→
    50→    const fn = ast.body[0] as any;
    51→    const stmt = fn.body[0] as any;
    52→    expect(stmt.value.type).toBe('Array');
    53→    expect(stmt.value.elements.length).toBe(0);
    54→  });
    55→
    56→  /**
    57→   * Test 3: 중첩 표현식 배열 [1+2, 3*4]
    58→   */
    59→  test('Test 3: 중첩 표현식 배열 [1+2, 3*4]', () => {
    60→    const code = `@mode(v)
    61→fn test() -> i64 {
    62→  let arr = [1 + 2, 3 * 4]
    63→  return 0
    64→}`;
    65→    const lexer = new NexusLexer(code);
    66→    const tokens = lexer.tokenize();
    67→    const parser = new NexusParser(tokens);
    68→    const ast = parser.parse();
    69→
    70→    const fn = ast.body[0] as any;
    71→    const stmt = fn.body[0] as any;
    72→    expect(stmt.value.type).toBe('Array');
    73→    expect(stmt.value.elements.length).toBe(2);
    74→    expect(stmt.value.elements[0].type).toBe('BinaryExpr');
    75→    expect(stmt.value.elements[1].type).toBe('BinaryExpr');
    76→  });
    77→
    78→  /**
    79→   * Test 4: 배열 인덱싱 파싱 arr[0]
    80→   */
    81→  test('Test 4: 배열 인덱싱 파싱 arr[0]', () => {
    82→    const code = `@mode(v)
    83→fn test() -> i64 {
    84→  let x = arr[0]
    85→  return 0
    86→}`;
    87→    const lexer = new NexusLexer(code);
    88→    const tokens = lexer.tokenize();
    89→    const parser = new NexusParser(tokens);
    90→    const ast = parser.parse();
    91→
    92→    const fn = ast.body[0] as any;
    93→    const stmt = fn.body[0] as any;
    94→    expect(stmt.value.type).toBe('ArrayAccess');
    95→    expect(stmt.value.object.type).toBe('Identifier');
    96→    expect((stmt.value.object as any).name).toBe('arr');
    97→    expect(stmt.value.index.type).toBe('Number');
    98→  });
    99→
   100→  /**
   101→   * Test 5: V 모드 배열 코드 생성 → C {1, 2, 3}
   102→   */
   103→  test('Test 5: V 모드 배열 코드 생성 → {1, 2, 3}', () => {
   104→    const code = `@mode(v)
   105→fn test() -> i64 {
   106→  let arr = [1, 2, 3]
   107→  return 0
   108→}`;
   109→    const lexer = new NexusLexer(code);
   110→    const tokens = lexer.tokenize();
   111→    const parser = new NexusParser(tokens);
   112→    const ast = parser.parse();
   113→    const codegen = new NexusCodegen();
   114→    const result = codegen.generate(ast);
   115→
   116→    expect(result.c).toContain('{1, 2, 3}');
   117→  });
   118→
   119→  /**
   120→   * Test 6: Python 모드 배열 코드 생성 → [1, 2, 3]
   121→   */
   122→  test('Test 6: Python 모드 배열 코드 생성 → [1, 2, 3]', () => {
   123→    const code = `@mode(python)
   124→def test():
   125→  arr = [1, 2, 3]
   126→  return 0`;
   127→    const lexer = new NexusLexer(code);
   128→    const tokens = lexer.tokenize();
   129→    const parser = new NexusParser(tokens);
   130→    const ast = parser.parse();
   131→    const codegen = new NexusCodegen();
   132→    const result = codegen.generate(ast);
   133→
   134→    expect(result.python).toContain('[1, 2, 3]');
   135→  });
   136→
   137→  /**
   138→   * Test 7: 배열 인덱싱 코드 생성 → arr[0]
   139→   */
   140→  test('Test 7: 배열 인덱싱 코드 생성 → arr[0]', () => {
   141→    const code = `@mode(v)
   142→fn test() -> i64 {
   143→  let x = arr[0]
   144→  return 0
   145→}`;
   146→    const lexer = new NexusLexer(code);
   147→    const tokens = lexer.tokenize();
   148→    const parser = new NexusParser(tokens);
   149→    const ast = parser.parse();
   150→    const codegen = new NexusCodegen();
   151→    const result = codegen.generate(ast);
   152→
   153→    expect(result.c).toContain('arr[0]');
   154→  });
   155→
   156→  /**
   157→   * Test 8: Trailing comma 지원 [1, 2, 3,]
   158→   */
   159→  test('Test 8: Trailing comma 지원 [1, 2, 3,]', () => {
   160→    const code = `@mode(v)
   161→fn test() -> i64 {
   162→  let arr = [1, 2, 3,]
   163→  return 0
   164→}`;
   165→    const lexer = new NexusLexer(code);
   166→    const tokens = lexer.tokenize();
   167→    const parser = new NexusParser(tokens);
   168→    const ast = parser.parse();
   169→
   170→    const fn = ast.body[0] as any;
   171→    const stmt = fn.body[0] as any;
   172→    expect(stmt.value.type).toBe('Array');
   173→    expect(stmt.value.elements.length).toBe(3);
   174→  });
   175→});
   176→

