     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string', 'int_cast']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    36→        // 탑레벨 문장은 V 모드(C)로 처리
    37→        this.genVStatement(fnItem as AST.Statement);
    38→      }
    39→    }
    40→
    41→    const c = this.cLines.join('\n');
    42→    const python = this.pyLines.join('\n');
    43→
    44→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    45→    const mixed =
    46→      c && python
    47→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    48→        : c || python;
    49→
    50→    return { c, python, mixed };
    51→  }
    52→
    53→  /**
    54→   * 실행 가능한 프로그램 생성
    55→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    56→   */
    57→  generateProgram(program: AST.Program): CodegenResult {
    58→    const base = this.generate(program);
    59→
    60→    // C 코드에 헤더 + main() wrapping 추가
    61→    const cWithMain = base.c
    62→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    63→      : '';
    64→
    65→    // Python 코드에 main 블록 추가
    66→    const pyWithMain = base.python
    67→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    68→      : '';
    69→
    70→    return {
    71→      c: cWithMain,
    72→      python: pyWithMain,
    73→      mixed: base.mixed,
    74→    };
    75→  }
    76→
    77→  /**
    78→   * V 함수 → C 함수
    79→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    80→   * →
    81→   * long long add(long long x, long long y) { return x + y; }
    82→   */
    83→  private genVFunction(fn: AST.VFunction): void {
    84→    // 반환타입
    85→    const returnType = this.mapVType(fn.returnType || 'void');
    86→
    87→    // 파라미터 리스트
    88→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    89→
    90→    // 함수 시그니처
    91→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    92→
    93→    // 함수 본문
    94→    this.indentLevel++;
    95→    for (const stmt of fn.body) {
    96→      this.genVStatement(stmt);
    97→    }
    98→    this.indentLevel--;
    99→
   100→    this.writeC('}');
   101→    this.writeC(''); // 빈 줄
   102→  }
   103→
   104→  /**
   105→   * Python 함수 → Python 함수
   106→   * def slow(items): return items
   107→   * →
   108→   * def slow(items):
   109→   *     return items
   110→   */
   111→  private genPyFunction(fn: AST.PyFunction): void {
   112→    // 파라미터 리스트
   113→    const paramList = fn.params.map((p) => p.name).join(', ');
   114→
   115→    // 함수 정의
   116→    this.writePy(`def ${fn.name}(${paramList}):`);
   117→
   118→    // 함수 본문 (들여쓰기 필요)
   119→    this.indentLevel++;
   120→    for (const stmt of fn.body) {
   121→      this.genPyStatement(stmt);
   122→    }
   123→    this.indentLevel--;
   124→
   125→    this.writePy(''); // 빈 줄
   126→  }
   127→
   128→  /**
   129→   * V 문장 생성 (C 코드용)
   130→   */
   131→  private genVStatement(stmt: AST.Statement): void {
   132→    const s = stmt as any;
   133→
   134→    if (s.type === 'Return') {
   135→      const returnStmt = s as AST.ReturnStatement;
   136→      if (returnStmt.value) {
   137→        const expr = this.genVExpression(returnStmt.value);
   138→        this.writeC(`${this.indent()}return ${expr};`);
   139→      } else {
   140→        this.writeC(`${this.indent()}return;`);
   141→      }
   142→    } else if (s.type === 'Assign') {
   143→      const assignStmt = s as AST.AssignStatement;
   144→      const expr = this.genVExpression(assignStmt.value);
   145→      // 값의 타입에 따라 C 타입 결정
   146→      const value = assignStmt.value as any;
   147→      let cType = 'long long'; // 기본값
   148→      if (value.type === 'String') {
   149→        cType = 'char*'; // 문자열 리터럴
   150→      }
   151→      this.writeC(`${this.indent()}${cType} ${assignStmt.name} = ${expr};`);
   152→    } else if (s.type === 'ExprStatement') {
   153→      const exprStmt = s as AST.ExprStatement;
   154→      const expr = this.genVExpression(exprStmt.expression);
   155→      this.writeC(`${this.indent()}${expr};`);
   156→    } else if (s.type === 'IfStatement') {
   157→      const ifStmt = s as AST.IfStatement;
   158→      const cond = this.genVExpression(ifStmt.condition);
   159→      this.writeC(`${this.indent()}if (${cond}) {`);
   160→      this.indentLevel++;
   161→      for (const stmt of ifStmt.thenBranch) {
   162→        this.genVStatement(stmt);
   163→      }
   164→      this.indentLevel--;
   165→      this.writeC(`${this.indent()}}`);
   166→      if (ifStmt.elseBranch) {
   167→        this.writeC(`${this.indent()}else {`);
   168→        this.indentLevel++;
   169→        for (const stmt of ifStmt.elseBranch) {
   170→          this.genVStatement(stmt);
   171→        }
   172→        this.indentLevel--;
   173→        this.writeC(`${this.indent()}}`);
   174→      }
   175→    }
   176→  }
   177→
   178→  /**
   179→   * Python 문장 생성 (Python 코드용)
   180→   */
   181→  private genPyStatement(stmt: AST.Statement): void {
   182→    const s = stmt as any;
   183→    const indentStr = this.indent();
   184→
   185→    if (s.type === 'Return') {
   186→      const returnStmt = s as AST.ReturnStatement;
   187→      if (returnStmt.value) {
   188→        const expr = this.genPyExpression(returnStmt.value);
   189→        this.writePy(`${indentStr}return ${expr}`);
   190→      } else {
   191→        this.writePy(`${indentStr}return`);
   192→      }
   193→    } else if (s.type === 'Assign') {
   194→      const assignStmt = s as AST.AssignStatement;
   195→      const expr = this.genPyExpression(assignStmt.value);
   196→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   197→    } else if (s.type === 'ExprStatement') {
   198→      const exprStmt = s as AST.ExprStatement;
   199→      const expr = this.genPyExpression(exprStmt.expression);
   200→      this.writePy(`${indentStr}${expr}`);
   201→    }
   202→  }
   203→
   204→  /**
   205→   * V 표현식 생성 (C 코드용)
   206→   */
   207→  private genVExpression(expr: AST.Expression): string {
   208→    const e = expr as any;
   209→
   210→    if (e.type === 'Number') {
   211→      return (e as AST.NumberLiteral).value.toString();
   212→    }
   213→
   214→    if (e.type === 'String') {
   215→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   216→      return (e as AST.StringLiteral).value;
   217→    }
   218→
   219→    if (e.type === 'Identifier') {
   220→      return (e as AST.Identifier).name;
   221→    }
   222→
   223→    if (e.type === 'BinaryExpr') {
   224→      const binExpr = e as AST.BinaryExpr;
   225→      const left = this.genVExpression(binExpr.left);
   226→      const right = this.genVExpression(binExpr.right);
   227→      return `${left} ${binExpr.operator} ${right}`;
   228→    }
   229→
   230→    if (e.type === 'Array') {
   231→      const arrayLit = e as AST.ArrayLiteral;
   232→      const elements = arrayLit.elements.map((el) => this.genVExpression(el)).join(', ');
   233→      return `{${elements}}`;
   234→    }
   235→
   236→    if (e.type === 'ArrayAccess') {
   237→      const arrayAccess = e as AST.ArrayAccess;
   238→      const obj = this.genVExpression(arrayAccess.object);
   239→      const idx = this.genVExpression(arrayAccess.index);
   240→      return `${obj}[${idx}]`;
   241→    }
   242→
   243→    if (e.type === 'Call') {
   244→      const callExpr = e as AST.CallExpr;
   245→
   246→      // callee가 Identifier인 경우 함수명 추출
   247→      let calleeStr: string | null = null;
   248→      if (typeof callExpr.callee === 'string') {
   249→        calleeStr = callExpr.callee;
   250→      } else {
   251→        const calleeExpr = callExpr.callee as any;
   252→        if (calleeExpr.type === 'Identifier') {
   253→          calleeStr = calleeExpr.name;
   254→        }
   255→      }
   256→
   257→      // V 내장 함수 처리
   258→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   259→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   260→      }
   261→
   262→      // 일반 함수 호출
   263→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   264→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   265→      return `${callee}(${args})`;
   266→    }
   267→
   268→    return '';
   269→  }
   270→
   271→  /**
   272→   * V 모드 내장 함수 호출 생성
   273→   */
   274→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   275→    if (name === 'println') {
   276→      if (args.length === 0) return 'printf("\\n")';
   277→      const firstArg = args[0] as any;
   278→      // StringLiteral인 경우: printf의 format string으로 사용
   279→      if (firstArg.type === 'String') {
   280→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   281→        const str = firstArg.value.slice(1, -1);
   282→        return `printf("${str}\\n")`;
   283→      }
   284→      // 숫자/식별자인 경우 %lld 포맷 사용
   285→      const arg = this.genVExpression(firstArg);
   286→      return `printf("%lld\\n", ${arg})`;
   287→    }
   288→
   289→    if (name === 'print') {
   290→      if (args.length === 0) return 'printf("")';
   291→      const firstArg = args[0] as any;
   292→      if (firstArg.type === 'String') {
   293→        // StringLiteral인 경우: printf의 format string으로 사용
   294→        const str = firstArg.value.slice(1, -1);
   295→        return `printf("${str}")`;
   296→      }
   297→      const arg = this.genVExpression(firstArg);
   298→      return `printf("%lld", ${arg})`;
   299→    }
   300→
   301→    if (name === 'len') {
   302→      const firstArg = args[0] as any;
   303→      if (firstArg.type === 'String') {
   304→        // StringLiteral인 경우 따옴표 제거
   305→        const str = firstArg.value.slice(1, -1);
   306→        return `strlen("${str}")`;
   307→      }
   308→      const arg = this.genVExpression(firstArg);
   309→      return `strlen(${arg})`;
   310→    }
   311→
   312→    if (name === 'to_string') {
   313→      const arg = this.genVExpression(args[0]);
   314→      return arg; // 단순 pass-through
   315→    }
   316→
   317→    if (name === 'int_cast') {
   318→      const firstArg = args[0] as any;
   319→      if (firstArg.type === 'String') {
   320→        const str = firstArg.value.slice(1, -1);
   321→        return `atoi("${str}")`;
   322→      }
   323→      const arg = this.genVExpression(firstArg);
   324→      return `atoi(${arg})`;
   325→    }
   326→
   327→    return '';
   328→  }
   329→
   330→  /**
   331→   * Python 표현식 생성 (Python 코드용)
   332→   */
   333→  private genPyExpression(expr: AST.Expression): string {
   334→    const e = expr as any;
   335→
   336→    if (e.type === 'Number') {
   337→      return (e as AST.NumberLiteral).value.toString();
   338→    }
   339→
   340→    if (e.type === 'String') {
   341→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   342→      return (e as AST.StringLiteral).value;
   343→    }
   344→
   345→    if (e.type === 'Identifier') {
   346→      return (e as AST.Identifier).name;
   347→    }
   348→
   349→    if (e.type === 'BinaryExpr') {
   350→      const binExpr = e as AST.BinaryExpr;
   351→      const left = this.genPyExpression(binExpr.left);
   352→      const right = this.genPyExpression(binExpr.right);
   353→      return `${left} ${binExpr.operator} ${right}`;
   354→    }
   355→
   356→    if (e.type === 'Array') {
   357→      const arrayLit = e as AST.ArrayLiteral;
   358→      const elements = arrayLit.elements.map((el) => this.genPyExpression(el)).join(', ');
   359→      return `[${elements}]`;
   360→    }
   361→
   362→    if (e.type === 'ArrayAccess') {
   363→      const arrayAccess = e as AST.ArrayAccess;
   364→      const obj = this.genPyExpression(arrayAccess.object);
   365→      const idx = this.genPyExpression(arrayAccess.index);
   366→      return `${obj}[${idx}]`;
   367→    }
   368→
   369→    if (e.type === 'Call') {
   370→      const callExpr = e as AST.CallExpr;
   371→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   372→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   373→      return `${callee}(${args})`;
   374→    }
   375→
   376→    return '';
   377→  }
   378→
   379→  /**
   380→   * V 타입 → C 타입 매핑
   381→   */
   382→  private mapVType(type: string): string {
   383→    const mapping: Record<string, string> = {
   384→      i64: 'long long',
   385→      i32: 'int',
   386→      f64: 'double',
   387→      f32: 'float',
   388→      bool: 'bool',
   389→      string: 'char*',
   390→      void: 'void',
   391→    };
   392→
   393→    return mapping[type] || type;
   394→  }
   395→
   396→  /**
   397→   * Python 타입 → Python 타입 (기본값)
   398→   */
   399→  private mapPyType(type: string): string {
   400→    const mapping: Record<string, string> = {
   401→      i64: 'int',
   402→      i32: 'int',
   403→      f64: 'float',
   404→      f32: 'float',
   405→      bool: 'bool',
   406→      string: 'str',
   407→      void: 'None',
   408→      int: 'int',
   409→      float: 'float',
   410→    };
   411→
   412→    return mapping[type] || type;
   413→  }
   414→
   415→  /**
   416→   * C 코드에 줄 추가
   417→   */
   418→  private writeC(line: string): void {
   419→    this.cLines.push(line);
   420→  }
   421→
   422→  /**
   423→   * Python 코드에 줄 추가
   424→   */
   425→  private writePy(line: string): void {
   426→    this.pyLines.push(line);
   427→  }
   428→
   429→  /**
   430→   * 현재 들여쓰기 문자열
